#!/bin/sh
# entropytest.sh - the random secrets of scubed3ctl and of the installer
# have at least 256 bits:
#
# 1. the autogenerated passphrase of scubed3ctl (ks_generate_passphrase,
#    taken from src/scubed3ctl.c as it is): 64 letters in groups of four,
#    16 different letters (every letter is 4 bits of getrandom(2): 256
#    bits); 20000 of them: the frequencies of the letters at every position
#    are uniform (chi-square), no passphrase twice
# 2. the autogenerated passphrase of the installer (s3_generate_passphrase
#    of partman-scubed3, from /dev/random): the same form, 300 of them, the
#    frequencies of the letters are uniform
# 3. the keys in the key store (scubed3ctl, with fake-cryptsetup): the LUKS
#    key that luksformat gives cryptsetup has 64 bytes (512 bits), the key
#    of a partition 32 bytes (256 bits), from getrandom(2), they differ
#    between partitions
#
# usage: entropytest.sh DAEMON CTL (as root)
D=$(realpath $1); C=$(realpath $2); T=$(mktemp -d); MNT=/mnt/s3
DEV=$(cd "$(dirname "$0")" && pwd); SRC=$DEV/../src
P=$DEV/../contrib/debian-installer/partman-scubed3
FUSERMOUNT=$(command -v fusermount3 || echo fusermount)
cleanup() { $FUSERMOUNT -u $MNT 2> /dev/null; wait; rm -rf $T; }
fail() { echo "ENTROPYTEST FAILED: $1"; cleanup; exit 1; }
ok() { echo "   ok: $1"; }

# the frequencies of the letters in the lines of a file, per position, and
# all together: chi-square with 15 degrees of freedom, p < 1e-6 fails
check() {
	python3 - "$1" << 'EOF'
import sys, math
lines = [l.rstrip("\n") for l in open(sys.argv[1])]
letters = "bcdefghjknprstuv"
form = all(len(l) == 79 and all((l[i] == " ") == (i % 5 == 4) for i in range(79))
	and all(c in letters for c in l.replace(" ", "")) for l in lines)
if not form:
	print("the form is wrong"); sys.exit(1)
if len(set(lines)) != len(lines):
	print("a passphrase twice"); sys.exit(1)
def chi2(counts):
	n = sum(counts); e = n/16
	return sum((c - e)**2/e for c in counts)
# p < 1e-6 with 15 degrees of freedom: chi-square > 61.1
worst = 0
for pos in range(64):
	col = [l.replace(" ", "")[pos] for l in lines]
	worst = max(worst, chi2([col.count(c) for c in letters]))
allc = "".join(l.replace(" ", "") for l in lines)
total = chi2([allc.count(c) for c in letters])
print("      %d passphrases, chi-square (15 degrees of freedom, limit 61.1, p = 1e-6):"
	" all letters %.1f, the worst of the 64 positions %.1f" % (len(lines), total, worst))
sys.exit(0 if total < 61.1 and worst < 61.1 else 1)
EOF
}

echo "1. the autogenerated passphrase of scubed3ctl"
# the function as it is in scubed3ctl.c, with getrandom(2)
{
	cat << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/random.h>
static void ks_random(void *buf, size_t len) {
	if (getrandom(buf, len, 0) != (ssize_t)len) exit(1);
}
static void *ecalloc(size_t n, size_t s) { return calloc(n, s); }
#define wipememory(p, n) memset(p, 0, n)
EOF
	sed -n '/^#define KS_GEN_GROUPS/,/^}/p' $SRC/scubed3ctl.c
	cat << 'EOF'
int main(int argc, char **argv) {
	int i, n = atoi(argv[1]);
	size_t len;
	for (i = 0; i < n; i++) {
		char *pw = ks_generate_passphrase(&len);
		if (len != strlen(pw)) return 1;
		printf("%s\n", pw);
		free(pw);
	}
	return 0;
}
EOF
} > $T/gen.c
grep -q '^#define KS_GEN_GROUPS	16$' $T/gen.c || fail "KS_GEN_GROUPS is not 16 in scubed3ctl.c"
${CC:-gcc} -O2 -o $T/gen $T/gen.c || fail "the generator does not compile"
$T/gen 20000 > $T/ctl.out || fail "the generator"
check $T/ctl.out || fail "the passphrases of scubed3ctl are not uniform"
ok "64 letters of 16 (4 bits each, from getrandom): 256 bits, uniform, no passphrase twice"

echo "2. the autogenerated passphrase of the installer"
mkdir -p $T/state
echo 'db_metaget() { return 0; }' > $T/base.sh
sed -e "s|/lib/partman/lib/base.sh|$T/base.sh|" -e "s|^S3STATE=.*|S3STATE=$T/state|" \
	$P/lib/scubed3-base.sh > $T/lib.sh
sh -c ". $T/lib.sh; i=0; while [ \$i -lt 300 ]; do s3_generate_passphrase || exit 1; i=\$((i + 1)); done" \
	> $T/sh.out || fail "s3_generate_passphrase"
check $T/sh.out || fail "the passphrases of the installer are not uniform"
[ -z "$(ls $T/state)" ] || fail "random data is left in the state directory"
ok "64 letters of 16 from /dev/random: 256 bits, uniform, nothing is left in the state directory"

echo "3. the keys in the key store"
mkdir -p $T/bin
# cryptsetup: the length of the key file that luksformat gives it
cat > $T/bin/cryptsetup << EOF
#!/bin/sh
case " \$* " in
*" luksFormat "*" --key-file=- "*|*" luksFormat --type luks2 --key-file=- "*)
	tee $T/lukskey.\$\$ | $DEV/fake-cryptsetup "\$@";;
*)	exec $DEV/fake-cryptsetup "\$@";;
esac
EOF
chmod +x $T/bin/cryptsetup
export PATH=$T/bin:$PATH
printf 'iterations=1000\n' > $T/s3.conf
head -c $((100<<16)) /dev/urandom > $T/base
$FUSERMOUNT -u -z $MNT 2> /dev/null
mkdir -p $MNT
$D -b $T/base -m 12 -M 16 -f $MNT > $T/log 2>&1 & sleep 0.5
ctl() { $C -q -YYY -C $T/s3.conf -K $T/keys "$@"; }
ctl -c keys-create > /dev/null
printf '\nA\nA\n' | ctl -c unlock-all -c keys-passphrase-add > /dev/null
printf 'A\n\n' | ctl -c unlock-all -c "keys-add p1 1" -c "keys-add p2 1" -c "create p1" \
	-c "create p2" -c "resize p1 10" -c "resize p2 10" -c "luksformat p1" \
	-c "luksformat p2" > $T/out 2>&1
set -- $T/lukskey.*
[ $# = 2 ] || fail "luksformat: $(cat $T/out)"
[ "$(wc -c < $1)" = 64 ] && [ "$(wc -c < $2)" = 64 ] || fail "a LUKS key has not 64 bytes"
cmp -s $1 $2 && fail "two LUKS volumes have the same key"
ok "the LUKS keys have 64 bytes (512 bits), they differ"
grep -q 'define KS_KEY		32' $SRC/keystore.h && grep -q 'ks_random(e->key, KS_KEY);' $SRC/scubed3ctl.c &&
	grep -q 'ks_random(e->luks, KS_LUKS);' $SRC/scubed3ctl.c || fail "the keys are not from ks_random"
# two partitions with keys from the store open as two partitions (the keys
# differ)
ctl -c p | grep -q " blocks in p1" && ctl -c p | grep -q " blocks in p2" || fail "p1 and p2: $(ctl -c p)"
ok "the keys of the partitions have 32 bytes (256 bits, KS_KEY = KEY_LENGTH), from getrandom"
for n in p1 p2; do ctl -c "close $n" > /dev/null; done
cleanup
echo "ENTROPYTEST OK"
